// ===== ตั้งค่า: แก้ 3 ค่านี้ครั้งเดียว =====
return [{
  json: {
    // อีเมลที่จะรับแจ้งเตือนเมื่อได้ไฟล์ใหม่ / ครบ 11 ไฟล์ — หลายคนคั่นด้วยจุลภาค เช่น 'a@company.com, b@company.com'
    notifyEmail: 'ใส่อีเมลของคุณ@example.com',
    // ID โฟลเดอร์ Google Drive ที่จะเก็บ Playlist (ดูจากลิงก์โฟลเดอร์: drive.google.com/drive/folders/<ID>)
    parentFolderId: 'ใส่_ID_โฟลเดอร์_Google_Drive',
    // ใส่อีเมลผู้ส่ง Playlist ถ้ามี (คั่นด้วย OR) เช่น 'a@company.com OR b@company.com' — เว้นว่าง = ดูทุกอีเมลที่มีไฟล์ Excel แนบ
    fromFilter: '',
    // Playlist 11 แบบที่ระบบเติมใบเช็ครูปต้องใช้ (ชื่อ + รูปแบบชื่อไฟล์)
    kinds: [
      { name: 'แยกจอ 40Blue', pattern: '40\\s*Blue' },
      { name: 'แยกจอ 40Red', pattern: '40\\s*Red' },
      { name: 'แยกจอ 80Blue', pattern: '80\\s*Blue' },
      { name: 'แยกจอ 80Red', pattern: '80\\s*Red' },
      { name: 'แยกจอ CITY', pattern: 'แยกจอ.*CITY|[_\\s]CITY[_\\s.]' },
      { name: 'แยกจอ Spare', pattern: 'Spare' },
      { name: 'Signature Max', pattern: 'Signature' },
      { name: 'Show DC', pattern: 'Show\\s*DC' },
      { name: 'BKJ1', pattern: 'BKJ\\s*1' },
      { name: 'BKJ2', pattern: 'BKJ\\s*2' },
      { name: 'Metro LED', pattern: 'Metro' },
    ],
  },
}];

// คัดไฟล์ Playlist 11 แบบจากอีเมลวันนี้ เลือกไฟล์ล่าสุดของแต่ละแบบ และข้ามไฟล์ที่อัปโหลดไปแล้ววันนี้
const cfg = $('ตั้งค่า').first().json;
const kinds = cfg.kinds.map(k => ({ name: k.name, re: new RegExp(k.pattern, 'i') }));
const sd = $getWorkflowStaticData('global');
const today = $now.setZone('Asia/Bangkok').toFormat('yyyy-MM-dd');
if (sd.day !== today) { sd.day = today; sd.sent = {}; sd.folderId = ''; }

const best = {};
const others = new Set(); // ไฟล์ Excel ที่ชื่อไม่ตรง 11 แบบ
for (const item of $input.all()) {
  const when = new Date(item.json.date || 0).getTime() || 0;
  for (const [prop, bin] of Object.entries(item.binary || {})) {
    const name = (bin.fileName || '').normalize('NFC');
    if (!/\.xlsx?$/i.test(name)) continue;
    const kind = kinds.find(k => k.re.test(name));
    if (!kind) { others.add(name); continue; }
    const key = kind.name + '|' + name + '|' + (bin.fileSize || '');
    if (!best[kind.name] || when >= best[kind.name].when) {
      best[kind.name] = { kind: kind.name, name, key, when, prop, item };
    }
  }
}

sd.others = [...others];

const out = [];
for (const b of Object.values(best)) {
  if (sd.sent[b.key]) continue; // อัปโหลดไปแล้ววันนี้
  out.push({
    json: { kind: b.kind, fileName: b.name, key: b.key, folderId: sd.folderId || '' },
    binary: { data: b.item.binary[b.prop] },
  });
}
return out;

// จำ ID โฟลเดอร์ของวันนี้ แล้วส่งไฟล์ทั้งหมดต่อไปอัปโหลด
const sd = $getWorkflowStaticData('global');
const folderId = $input.first().json.id;
sd.folderId = folderId;
return $('คัดไฟล์ Playlist').all().map(i => ({
  json: { ...i.json, folderId },
  binary: i.binary,
}));

// บันทึกว่าอัปโหลดไฟล์ไหนแล้ว และเขียนอีเมลสรุปว่าวันนี้ได้ครบ 11 ไฟล์หรือยัง
const cfg = $('ตั้งค่า').first().json;
const sd = $getWorkflowStaticData('global');
const picked = $('คัดไฟล์ Playlist').all();
const before = new Set(Object.values(sd.sent));
const replaced = picked.filter(p => before.has(p.json.kind)).map(p => p.json.kind);
for (const p of picked) sd.sent[p.json.key] = p.json.kind;

const all = cfg.kinds.map(k => k.name);
const have = new Set(Object.values(sd.sent));
const missing = all.filter(k => !have.has(k));
const day = $now.setZone('Asia/Bangkok').setLocale('th').toFormat('d LLL yyyy');
const link = 'https://drive.google.com/drive/folders/' + sd.folderId;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');

const status = missing.length
  ? `<p>ยังขาด <b>${missing.length}</b> ไฟล์: ${missing.map(esc).join(', ')}</p><p>ระบบจะเช็กอีเมลอีกครั้งในชั่วโมงถัดไป (ถึง 12:00)</p>`
  : `<p><b>ครบ 11 ไฟล์แล้ว</b> ดาวน์โหลดทั้งโฟลเดอร์ แล้วลากลงระบบเติมใบเช็ครูปได้เลย</p>`;

const html = `<div style="font-family:Tahoma,sans-serif;font-size:15px;line-height:1.6">
<p>Playlist วันที่ ${esc(day)} — ได้แล้ว <b>${have.size}/${all.length}</b> ไฟล์</p>
<p>ไฟล์ที่เพิ่งเข้าโฟลเดอร์รอบนี้:</p>
<ul>${picked.map(p => `<li>${esc(p.json.kind)}: ${esc(p.json.fileName)}</li>`).join('')}</ul>
${status}
${replaced.length ? `<p style="color:#b35a14"><b>มีไฟล์ฉบับใหม่เข้ามาแทน:</b> ${replaced.map(esc).join(', ')} — ลบไฟล์เก่าของแบบนี้ในโฟลเดอร์ก่อนนำไปใช้</p>` : ''}
${(sd.others || []).length ? `<p style="color:#586274">ไฟล์ Excel อื่นในอีเมลวันนี้ (ไม่ได้เก็บ เพราะชื่อไม่ตรง 11 แบบ):</p><ul style="color:#586274">${sd.others.map(n => `<li>${esc(n)}</li>`).join('')}</ul>` : ''}
<p><a href="${link}">เปิดโฟลเดอร์ Google Drive ของวันนี้</a></p>
</div>`;

return [{
  json: {
    to: cfg.notifyEmail,
    subject: `Playlist ${day}: ${have.size}/${all.length} ไฟล์` + (missing.length ? ' (ยังไม่ครบ)' : ' — ครบแล้ว'),
    html,
  },
}];
